import math

from ...processing_utils import MultiModalData, ProcessorMixin
from ...utils import auto_docstring


@auto_docstring
class MiniCPMV4_5Processor(ProcessorMixin):
    def __init__(
        self,
        image_processor=None,
        video_processor=None,
        tokenizer=None,
        chat_template=None,
        image_token: str = "<unk>",
        video_token: str = "<|video_pad|>",
        image_start_token: str = "<image>",
        image_end_token: str = "</image>",
        slice_start_token: str = "<slice>",
        slice_end_token: str = "</slice>",
        num_image_tokens: int = 64,
        **kwargs,
    ):
        r"""
        image_token (`str`, *optional*, defaults to `"<unk>"`):
            Marks an image in the text, and is repeated `num_image_tokens` times per image slice.
        video_token (`str`, *optional*, defaults to `"<|video_pad|>"`):
            Marks a video in the text, and is repeated `num_image_tokens` times per slice of each group of frames.
        image_start_token (`str`, *optional*, defaults to `"<image>"`):
            Opens the image tokens of the overview image.
        image_end_token (`str`, *optional*, defaults to `"</image>"`):
            Closes the image tokens of the overview image.
        slice_start_token (`str`, *optional*, defaults to `"<slice>"`):
            Opens the image tokens of one slice.
        slice_end_token (`str`, *optional*, defaults to `"</slice>"`):
            Closes the image tokens of one slice.
        num_image_tokens (`int`, *optional*, defaults to 64):
            Number of image tokens per slice (the resampler's number of latents).
        """
        self.image_token = image_token
        self.video_token = video_token
        self.image_start_token = image_start_token
        self.image_end_token = image_end_token
        self.slice_start_token = slice_start_token
        self.slice_end_token = slice_end_token
        self.num_image_tokens = num_image_tokens
        super().__init__(image_processor, video_processor, tokenizer, chat_template=chat_template, **kwargs)
        self.image_token_id = tokenizer.convert_tokens_to_ids(self.image_token)
        self.video_token_id = tokenizer.convert_tokens_to_ids(self.video_token)

    def replace_image_token(self, image_inputs: dict, image_idx: int, **kwargs) -> str:
        # Overview image, then each slice in its own <slice>...</slice>, one line per row of slices
        image_tokens = self.image_token * self.num_image_tokens
        num_rows, num_cols = image_inputs["grids"][image_idx]
        rows = [(self.slice_start_token + image_tokens + self.slice_end_token) * num_cols for _ in range(num_rows)]
        return self.image_start_token + image_tokens + self.image_end_token + "\n".join(rows)

    @property
    def unused_input_names(self) -> list[str]:
        return ["grids", "grids_videos", "num_groups_per_video"]

    def _get_num_multimodal_tokens(self, image_sizes=None, video_sizes=None, **kwargs):
        """
        Computes the number of placeholder tokens needed for multimodal inputs with the given sizes.

        Args:
            image_sizes (`list[list[int]]`, *optional*):
                The input sizes formatted as (height, width) per each image.
            video_sizes (`list[list[int]]`, *optional*):
                The input sizes formatted as (num_frames, height, width) per each video, with the frames taken as
                sampled at `fps`.

        Returns:
            `MultiModalData`: A `MultiModalData` object holding number of tokens per each of the provided
            input modalities, along with other useful data.
        """
        vision_data = {}
        output_kwargs = self._merge_kwargs(**kwargs)
        if image_sizes is not None:
            images_kwargs = output_kwargs["images_kwargs"]
            max_slice_nums = images_kwargs.get("max_slice_nums") or self.image_processor.max_slice_nums
            scale_resolution = images_kwargs.get("scale_resolution") or self.image_processor.scale_resolution
            slice_mode = images_kwargs.get("slice_mode", self.image_processor.slice_mode)

            num_image_patches = []
            for image_size in image_sizes:
                grid = self.image_processor.get_sliced_grid(image_size, max_slice_nums, scale_resolution)
                num_image_patches.append(1 + grid[0] * grid[1] if slice_mode and grid is not None else 1)
            num_image_tokens = [self.num_image_tokens * num_patches for num_patches in num_image_patches]
            vision_data.update({"num_image_tokens": num_image_tokens, "num_image_patches": num_image_patches})

        if video_sizes is not None:
            videos_kwargs = output_kwargs["videos_kwargs"]
            video_processor = self.video_processor
            fps = videos_kwargs.get("fps") or video_processor.fps
            max_num_frames = videos_kwargs.get("max_num_frames") or video_processor.max_num_frames
            max_num_packing = videos_kwargs.get("max_num_packing") or video_processor.max_num_packing
            max_slice_nums = videos_kwargs.get("max_slice_nums") or video_processor.max_slice_nums
            scale_resolution = videos_kwargs.get("scale_resolution") or video_processor.scale_resolution
            slice_mode = videos_kwargs.get("slice_mode", video_processor.slice_mode)

            num_video_tokens = []
            for num_frames, height, width in video_sizes:
                num_packing = video_processor.get_num_packing(num_frames / fps, fps, max_num_frames, max_num_packing)
                grid = video_processor.get_sliced_grid((height, width), max_slice_nums, scale_resolution)
                num_slices = 1 + grid[0] * grid[1] if slice_mode and grid is not None else 1
                num_video_tokens.append(math.ceil(num_frames / num_packing) * num_slices * self.num_image_tokens)
            vision_data["num_video_tokens"] = num_video_tokens

        return MultiModalData(**vision_data)

    def replace_video_token(self, video_inputs: dict, video_idx: int, **kwargs) -> str:
        # One placeholder per group of frames, laid out like an image, one line per group
        video_tokens = self.video_token * self.num_image_tokens
        num_rows, num_cols = video_inputs["grids_videos"][video_idx]
        rows = [(self.slice_start_token + video_tokens + self.slice_end_token) * num_cols for _ in range(num_rows)]
        group = self.image_start_token + video_tokens + self.image_end_token + "\n".join(rows)
        return "\n".join([group] * video_inputs["num_groups_per_video"][video_idx])


__all__ = ["MiniCPMV4_5Processor"]
